describe('Hyper Pulse mob skill',function()
 it('uses its slashing plan, preserves Bind on damage, and applies Bind only after processing',function()
  local pulse=require('scripts/actions/mobskills/hyper_pulse');local move,process,effect=xi.mobskills.mobPhysicalMove,xi.mobskills.processDamage,xi.mobskills.mobStatusEffectMove;local params,damage,bind=nil,nil,nil;local mob={getWeaponDmg=function()return 77 end};local target={takeDamage=function(_,...)damage={...}end};xi.mobskills.mobPhysicalMove=function(_,_,_,_,v)params=v;return {damage=123,attackType=xi.attackType.PHYSICAL,damageType=xi.damageType.SLASHING}end;xi.mobskills.processDamage=function()return false end;xi.mobskills.mobStatusEffectMove=function(_,_,...)bind={...}end
  assert(pulse.onMobSkillCheck(target,mob,{})==0 and pulse.onMobWeaponSkill(mob,target,{},{})==123);assert(params.baseDamage==77 and params.numHits==1 and params.fTP[1]==1 and params.fTP[2]==1 and params.fTP[3]==1 and params.attackType==xi.attackType.PHYSICAL and params.damageType==xi.damageType.SLASHING and params.shadowBehavior==xi.mobskills.shadowBehavior.WIPE_SHADOWS and damage==nil and bind==nil);xi.mobskills.processDamage=function()return true end;pulse.onMobWeaponSkill(mob,target,{},{})
  xi.mobskills.mobPhysicalMove,xi.mobskills.processDamage,xi.mobskills.mobStatusEffectMove=move,process,effect;assert(damage[1]==123 and damage[2]==mob and damage[3]==xi.attackType.PHYSICAL and damage[4]==xi.damageType.SLASHING and damage[5].breakBind==false);assert(bind[1]==xi.effect.BIND and bind[2]==1 and bind[3]==0 and bind[4]==15)
 end)
end)
